// Snap mode's preview: the route a click would make, drawn while the mouse moves. One shortest-distance tree is worked
// out from the route's last point over the roads around it (the solve worker runs distanceTree); after that each
// mouse move only snaps the cursor onto the nearest road (roadIndex + nearestRoad) and walks the tree back (pathTo).
// Distances are the Snap search's (weights.mjs P.flat): every road piece costs its length, an avoided one (factor
// Infinity) is closed. Pure: graph in, arrays out (CONTRACT.md §2 typed graph); it runs in Node (test/snap-tree.mjs).
const KY = 110574, kxAt = (lat) => Math.cos((lat * Math.PI) / 180) * 111320;

// the cost of riding chain c end to end: its atoms' lengths, each times its factor (Infinity: closed)
export function chainCosts(graph, noteF = null) {
  const out = new Float64Array(graph.nChains);
  for (let c = 0; c < graph.nChains; c++) {
    let s = 0;
    for (let i = graph.atomStart[c]; i < graph.atomStart[c + 1]; i++) s += graph.atomLen[i] * (noteF?.[i] || 1);
    out[c] = s;
  }
  return out;
}

// A shortest-distance tree from seeds [{ node, cost }]: dist (metres, Infinity: not reached) and via (the chain each
// node was reached by, -1 for a seed or a node not reached).
export function distanceTree(graph, seeds, noteF = null) {
  const n = graph.nNodes, cost = chainCosts(graph, noteF);
  // node -> chains (CSR)
  const deg = new Int32Array(n + 1);
  for (let c = 0; c < graph.nChains; c++) { deg[graph.chainA[c] + 1]++; deg[graph.chainB[c] + 1]++; }
  for (let v = 0; v < n; v++) deg[v + 1] += deg[v];
  const adj = new Int32Array(deg[n]), fill = deg.slice(0, n);
  for (let c = 0; c < graph.nChains; c++) { adj[fill[graph.chainA[c]]++] = c; adj[fill[graph.chainB[c]]++] = c; }
  const dist = new Float64Array(n).fill(Infinity), via = new Int32Array(n).fill(-1), done = new Uint8Array(n);
  // binary heap of (cost, node)
  let hk = new Float64Array(64), hv = new Int32Array(64), hn = 0;
  const push = (k, v) => {
    if (hn === hk.length) { const k2 = new Float64Array(hn * 2), v2 = new Int32Array(hn * 2); k2.set(hk); v2.set(hv); hk = k2; hv = v2; }
    let i = hn++;
    while (i > 0) { const p = (i - 1) >> 1; if (hk[p] <= k) break; hk[i] = hk[p]; hv[i] = hv[p]; i = p; }
    hk[i] = k; hv[i] = v;
  };
  const pop = () => {
    const v = hv[0], k = hk[--hn], last = hv[hn];
    let i = 0;
    for (;;) { let c = 2 * i + 1; if (c >= hn) break; if (c + 1 < hn && hk[c + 1] < hk[c]) c++; if (hk[c] >= k) break; hk[i] = hk[c]; hv[i] = hv[c]; i = c; }
    hk[i] = k; hv[i] = last;
    return v;
  };
  for (const s of seeds) if (s.cost < dist[s.node]) { dist[s.node] = s.cost; via[s.node] = -1; push(s.cost, s.node); }
  while (hn) {
    const u = pop(); if (done[u]) continue; done[u] = 1;
    const du = dist[u];
    for (let j = deg[u]; j < deg[u + 1]; j++) {
      const c = adj[j], w = cost[c]; if (w === Infinity) continue;
      const v = graph.chainA[c] === u ? graph.chainB[c] : graph.chainA[c];
      if (du + w < dist[v]) { dist[v] = du + w; via[v] = c; push(dist[v], v); }
    }
  }
  return { dist, via };
}

// A grid over the chains' polylines (cells of cellM metres), so the road nearest the cursor is found without
// looking at every chain.
export function roadIndex(graph, cellM = 250) {
  const lat0 = graph.nNodes ? graph.nodeLat[0] : 35, kx = kxAt(lat0), cx = cellM / kx, cy = cellM / KY, cells = new Map();
  for (let c = 0; c < graph.nChains; c++) {
    for (let k = graph.coordStart[c] + 1; k < graph.coordStart[c + 1]; k++) {
      const x0 = Math.floor(Math.min(graph.coordLon[k - 1], graph.coordLon[k]) / cx), x1 = Math.floor(Math.max(graph.coordLon[k - 1], graph.coordLon[k]) / cx);
      const y0 = Math.floor(Math.min(graph.coordLat[k - 1], graph.coordLat[k]) / cy), y1 = Math.floor(Math.max(graph.coordLat[k - 1], graph.coordLat[k]) / cy);
      for (let x = x0; x <= x1; x++) for (let y = y0; y <= y1; y++) {
        const key = x * 1e6 + y; let a = cells.get(key); if (!a) cells.set(key, (a = []));
        if (a[a.length - 1] !== c) a.push(c);
      }
    }
  }
  return { cx, cy, cellM, cells };
}

// The nearest point of any chain to ll within maxM: { c, d (metres along the chain's polyline from its start), L (the
// polyline's length), ll, distM }, or null. Same projection and answer as snap.mjs snapPoint.
export function nearestRoad(graph, index, ll, maxM = 1000) {
  const [px, py] = ll, kx = kxAt(py), r = Math.ceil(maxM / index.cellM);
  const gx = Math.floor(px / index.cx), gy = Math.floor(py / index.cy), seen = new Set();
  let best = null;
  for (let x = gx - r; x <= gx + r; x++) for (let y = gy - r; y <= gy + r; y++) {
    for (const c of index.cells.get(x * 1e6 + y) ?? []) {
      if (seen.has(c)) continue; seen.add(c);
      let along = 0, hit = null;
      for (let k = graph.coordStart[c] + 1; k < graph.coordStart[c + 1]; k++) {
        const x0 = graph.coordLon[k - 1], y0 = graph.coordLat[k - 1], x1 = graph.coordLon[k], y1 = graph.coordLat[k];
        const ax = (x0 - px) * kx, ay = (y0 - py) * KY, dx = (x1 - x0) * kx, dy = (y1 - y0) * KY, L = Math.hypot(dx, dy);
        const u = L ? Math.max(0, Math.min(1, -(ax * dx + ay * dy) / (L * L))) : 0, d = Math.hypot(ax + u * dx, ay + u * dy);
        if (d <= maxM && (!hit || d < hit.distM)) hit = { c, d: along + u * L, ll: [x0 + u * (x1 - x0), y0 + u * (y1 - y0)], distM: d };
        along += L;
      }
      if (hit && (!best || hit.distM < best.distM)) best = { ...hit, L: along };
    }
  }
  return best;
}

// chain c's polyline between d0 and d1 metres along it (reversed when d0 > d1), at latitude lat's projection
function subLine(graph, c, d0, d1, kx) {
  const s = graph.coordStart[c], e = graph.coordStart[c + 1], lo = Math.min(d0, d1), hi = Math.max(d0, d1), out = [];
  let along = 0;
  const at = (k, f) => [graph.coordLon[k - 1] + f * (graph.coordLon[k] - graph.coordLon[k - 1]), graph.coordLat[k - 1] + f * (graph.coordLat[k] - graph.coordLat[k - 1])];
  for (let k = s + 1; k < e; k++) {
    const L = Math.hypot((graph.coordLon[k] - graph.coordLon[k - 1]) * kx, (graph.coordLat[k] - graph.coordLat[k - 1]) * KY), a = along, b = along + L;
    if (b >= lo && a <= hi) {
      if (!out.length) out.push(at(k, L ? Math.max(0, (lo - a) / L) : 0));
      if (b <= hi) out.push([graph.coordLon[k], graph.coordLat[k]]); else { out.push(at(k, L ? (hi - a) / L : 1)); break; }
    }
    along = b;
  }
  if (out.length === 1) out.push(out[0]);
  return d0 > d1 ? out.reverse() : out;
}
const chainLine = (graph, c, fromNode) => {
  const out = [];
  for (let k = graph.coordStart[c]; k < graph.coordStart[c + 1]; k++) out.push([graph.coordLon[k], graph.coordLat[k]]);
  return graph.chainA[c] === fromNode ? out : out.reverse();
};

// The tree's seeds for a start on a road (nearestRoad's answer): both ends of its chain, each at the share of the
// chain's cost it lies from the start.
export function treeSeeds(graph, start, cost) {
  const f = start.L ? start.d / start.L : 0, w = cost[start.c];
  return [{ node: graph.chainA[start.c], cost: f * w }, { node: graph.chainB[start.c], cost: (1 - f) * w }];
}

// The way from the start to `end` (both nearestRoad answers) through the tree: { coords, costM }, or null when the
// end's road is not reached.
export function pathTo(graph, tree, start, end, cost) {
  const kx = kxAt(start.ll[1]), fe = end.L ? end.d / end.L : 0, we = cost[end.c];
  const cands = [];
  if (end.c === start.c && cost[start.c] < Infinity) cands.push({ costM: Math.abs((start.L ? start.d / start.L : 0) - fe) * we, direct: true });
  if (we < Infinity) {
    const A = graph.chainA[end.c], B = graph.chainB[end.c];
    cands.push({ costM: tree.dist[A] + fe * we, node: A, endD: 0 }, { costM: tree.dist[B] + (1 - fe) * we, node: B, endD: end.L });
  }
  const best = cands.filter((x) => x.costM < Infinity).sort((a, b) => a.costM - b.costM)[0];
  if (!best) return null;
  if (best.direct) return { coords: subLine(graph, start.c, start.d, end.d, kx), costM: best.costM };
  // walk back from the end's node to a seed (an end of the start's chain)
  const pieces = []; let v = best.node;
  for (let guard = 0; tree.via[v] >= 0 && guard < graph.nNodes; guard++) {
    const c = tree.via[v], u = graph.chainA[c] === v ? graph.chainB[c] : graph.chainA[c];
    pieces.push(chainLine(graph, c, u)); v = u;
  }
  const seedD = v === graph.chainA[start.c] ? 0 : start.L;
  const coords = subLine(graph, start.c, start.d, seedD, kx);
  for (let i = pieces.length - 1; i >= 0; i--) coords.push(...pieces[i].slice(1));
  coords.push(...subLine(graph, end.c, best.endD, end.d, kx).slice(1));
  return { coords, costM: best.costM };
}
