// The route being planned (CONTRACT.md §5c): a start flag, then control points, with a segment between each two
// neighbours. Every segment has its own mode, and once worked out its own frozen geometry:
//   'auto'  the routing engine (lowest-resistance route with alternatives) between its two points
//   'snap'  the shortest way along the roads, each point snapped onto the road (snap.mjs)
//   'line'  a straight line that ignores the map (elev.mjs)
//
//   plan = { points: [[lon, lat], ...],   points[0] is the start flag
//            segs:   [{ id, mode, status, route, opt, committed, error? }, ...]   segs[i]: points[i] -> points[i + 1]
//            ended:  boolean,             an end flag on the last point
//            avoids: [{ id, coords }] }   roads the rider avoided (avoids.mjs)
//   status: 'pending' (to be worked out) | 'working' | 'done' | 'error'
//   route:  the result (best-route.mjs shape); for an automatic segment that is still being decided (the last one, not
//           committed) it carries its alternatives, and opt is the chosen one (0 = ★ Best)
//   committed: the rider moved on (tapped the next point, or ended the route); its chosen option is the route, and
//           its alternatives are dropped
// Every edit returns a new plan (the old one is kept by Undo). Pure: runs in Node (test/plan.mjs).
import { packRoute, unpackRoute, splitLegs } from './tour.mjs';

export const MODES = ['snap', 'auto', 'line'];
const KY = 110574, kxAt = (lat) => Math.cos((lat * Math.PI) / 180) * 111320;
export const crowM = (a, b) => Math.hypot((a[0] - b[0]) * kxAt((a[1] + b[1]) / 2), (a[1] - b[1]) * KY);
const clamp = (v, lo, hi) => Math.min(hi, Math.max(lo, v));

// Search width of an automatic segment from its crow-flies length: 0.17 x L, rounded to 500 m, 1.5 km .. 25 km
// (100 km -> 17 km, 30 km -> 5 km, 5 km -> 1.5 km).
export const AUTO_RATIO = 0.17, AUTO_MIN_M = 1500, AUTO_MAX_M = 25000;
export const autoBufM = (L) => clamp(Math.round((AUTO_RATIO * L) / 500) * 500, AUTO_MIN_M, AUTO_MAX_M);
// Snap: the shortest way along roads, in a corridor of 0.5 x L, 1 km .. 5 km (a mountain road between two taps can
// wander far from the straight line)
export const snapBufM = (L) => clamp(Math.round((0.5 * L) / 100) * 100, 1000, 5000);

export const emptyPlan = () => ({ points: [], segs: [], ended: false, avoids: [] });
let segSeq = 0; // every new segment has an id of its own: a result in the making finds its segment by it (or knows it is gone)
export const newSeg = (mode, committed = false) => ({ id: `s${++segSeq}`, mode, status: 'pending', route: null, opt: 0, committed });
const P2 = (ll) => [+ll[0], +ll[1]];
export function clonePlan(p) {
  return { points: p.points.map((q) => q.slice()), segs: p.segs.map((s) => ({ ...s })), ended: !!p.ended, avoids: p.avoids.slice() };
}
// the route a segment rides: its chosen option
export function segRoute(s) {
  const r = s?.route; if (!r || r.error) return null;
  return s.opt > 0 ? r.alternatives?.[s.opt - 1] ?? r : r;
}
// the options of a segment: ★ Best and its alternatives
export const segOptions = (s) => (s?.route && !s.route.error ? [s.route, ...(s.route.alternatives ?? []).filter((r) => r.coords?.length >= 2)] : []);
const commit = (s) => (s.committed ? s : { ...s, committed: true, ...(s.route && s.status === 'done' ? { route: { ...segRoute(s), alternatives: [] }, opt: 0 } : {}) });
// the segment still being decided: the last one, automatic, not committed, the route not ended (-1: none)
export function activeSeg(p) {
  const k = p.segs.length - 1;
  return k >= 0 && !p.ended && p.segs[k].mode === 'auto' && !p.segs[k].committed ? k : -1;
}

// a tap on the map: the start flag, or the next control point with a new segment in `mode` (the last one is
// committed with its chosen option)
export function addPoint(p0, ll, mode) {
  const p = clonePlan(p0);
  if (p.ended) return p;
  if (p.segs.length) p.segs[p.segs.length - 1] = commit(p.segs[p.segs.length - 1]);
  p.points.push(P2(ll));
  if (p.points.length > 1) p.segs.push(newSeg(mode));
  return p;
}
// move control point k (the start flag is 0): its two segments are worked out again, each in its own mode
export function movePoint(p0, k, ll) {
  const p = clonePlan(p0);
  p.points[k] = P2(ll);
  for (const j of [k - 1, k]) if (p.segs[j]) p.segs[j] = { ...newSeg(p.segs[j].mode, p.segs[j].committed || j < p.segs.length - 1) };
  return p;
}
// drop a new control point into segment i at ll (dragging the route): both halves are worked out again in its mode
export function insertPoint(p0, i, ll) {
  const p = clonePlan(p0), s = p.segs[i];
  p.points.splice(i + 1, 0, P2(ll));
  p.segs.splice(i, 1, newSeg(s.mode, true), newSeg(s.mode, s.committed));
  return p;
}
// remove control point k: the start (the next point becomes the start), the last point, or one between two segments
// (they merge into one, in the earlier one's mode)
export function removePoint(p0, k) {
  let p = clonePlan(p0);
  const n = p.points.length;
  if (k === 0) return removeStart(p);
  if (k === n - 1) { p.points.pop(); p.segs.pop(); p.ended = false; return p; }
  const mode = p.segs[k - 1].mode, committed = p.segs[k].committed;
  p.points.splice(k, 1);
  p.segs.splice(k - 1, 2, newSeg(mode, committed));
  return p;
}
export function removeStart(p0) {
  const p = clonePlan(p0);
  p.points.shift(); p.segs.shift();
  if (p.points.length < 2) p.ended = false;
  return p;
}
// End route: the end flag on the last point; the last segment is committed
export function endPlan(p0) {
  const p = clonePlan(p0);
  if (p.points.length < 2) return p;
  p.segs[p.segs.length - 1] = commit(p.segs[p.segs.length - 1]);
  p.ended = true;
  return p;
}
export function unend(p0) { const p = clonePlan(p0); p.ended = false; return p; }
// Finish here (loop): a last segment back to the start flag, in `mode`, and the end flag
export const closeLoop = (p0, mode) => endPlan(addPoint(p0, p0.points[0], mode));
// The rider chose option i of the active segment
export function chooseOption(p0, k, i) { const p = clonePlan(p0); p.segs[k] = { ...p.segs[k], opt: i }; return p; }
// a segment's result arrived: done, keeping the option chosen before when it still exists
export function setResult(p0, k, route, extra = {}) {
  const p = clonePlan(p0), s = p.segs[k];
  if (!route || route.error) p.segs[k] = { ...s, status: 'error', route: null, error: route?.error ?? 'no route', ...extra };
  else {
    const opt = s.opt < 1 + (route.alternatives?.length ?? 0) ? s.opt : 0;
    p.segs[k] = s.committed ? { ...s, status: 'done', route: { ...route, alternatives: [] }, opt: 0, error: null, ...extra } : { ...s, status: 'done', route, opt, error: null, ...extra };
  }
  return p;
}
// every snap / auto segment whose route rides `avoid` goes back to pending (lineUses from avoids.mjs)
export function rerouteUsing(p0, lineUses, avoid) {
  const p = clonePlan(p0);
  p.segs = p.segs.map((s) => (s.mode !== 'line' && s.route && lineUses(segRoute(s)?.coords ?? [], avoid) ? newSeg(s.mode, s.committed) : s));
  return p;
}
export function addAvoid(p0, avoid) { const p = clonePlan(p0); p.avoids = [...p.avoids, avoid]; return p; }
export function removeAvoid(p0, id) { const p = clonePlan(p0); p.avoids = p.avoids.filter((a) => a.id !== id); return p; }
// every snap / auto segment back to pending (↻ Refresh: today's map data and settings)
export function refreshAll(p0) { const p = clonePlan(p0); p.segs = p.segs.map((s) => (s.mode === 'line' ? s : newSeg(s.mode, s.committed))); return p; }

// ---- saved route record (format v3, CONTRACT.md §5d) ----
// { v: 3, plan: { points, ended, avoids, segs: [{ mode, opt: 0, route: packRoute(the chosen route) | null }] }, settings, props }
export function planRecord(p, extra = {}) {
  return { v: 3, ...extra, plan: { points: p.points.map((q) => q.slice()), ended: !!p.ended, avoids: p.avoids.map((a) => ({ id: a.id, coords: a.coords })),
    segs: p.segs.map((s) => { const r = segRoute(s); return { mode: s.mode, route: r && s.status === 'done' ? packRoute(r) : null }; }) } };
}
// a saved record (v3, or v1 / v2 of the stop-by-stop planner, or a link's points) as a plan; every segment that came
// with its route is done and committed, the rest is pending
export function planFromRecord(rec) {
  if (rec?.v === 3) {
    const q = rec.plan;
    return { points: q.points.map(P2), ended: !!q.ended, avoids: (q.avoids ?? []).slice(),
      segs: q.segs.map((s) => (s.route ? { ...newSeg(s.mode, true), status: 'done', route: unpackRoute(s.route) } : newSeg(s.mode, true))) };
  }
  if (rec?.v === 2) { // a route of legs between stops: each leg is an automatic segment with its saved route
    const pts = (rec.parts ?? []).flat(), legs = splitLegs(pts), p = { points: [], segs: [], ended: legs.length > 0, avoids: [] };
    legs.forEach((l, k) => {
      if (!k) p.points.push(P2(pts[l.from]));
      p.points.push(P2(pts[l.to]));
      const r = rec.legs?.length === legs.length ? rec.legs[k].route : null;
      p.segs.push(r ? { ...newSeg('auto', true), status: 'done', route: unpackRoute(r) } : newSeg('auto', true));
    });
    return p;
  }
  if (rec?.v === 1) { // an old starred route: one line
    const pts = (rec.parts ?? []).flat(); if (pts.length < 2) return emptyPlan();
    const r = rec.route?.coords?.length >= 2 ? { ...rec.route, coords: rec.route.coords.map((c) => [c[0], c[1]]), alternatives: [] } : null;
    return { points: [P2(pts[0]), P2(pts.at(-1))], ended: true, avoids: [], segs: [r ? { ...newSeg('auto', true), status: 'done', route: r } : newSeg('auto', true)] };
  }
  return emptyPlan();
}
// a link's points ([lon, lat, ...]): the start and automatic segments through the rest, ended
export function planFromPoints(pts) {
  const p = emptyPlan();
  for (const q of pts) { p.points.push(P2(q)); if (p.points.length > 1) p.segs.push(newSeg('auto', true)); }
  p.ended = p.points.length > 1;
  return p;
}

// ---- a record as JSON (online routes, share links): typed arrays as base64 ----
const TA = { Float64Array, Float32Array, Int32Array, Uint8Array, Uint16Array, Int16Array, Uint32Array };
const b64 = (u8) => { if (typeof Buffer !== 'undefined') return Buffer.from(u8.buffer, u8.byteOffset, u8.byteLength).toString('base64'); let s = ''; for (let i = 0; i < u8.length; i += 0x8000) s += String.fromCharCode(...u8.subarray(i, i + 0x8000)); return btoa(s); };
const unb64 = (s) => { if (typeof Buffer !== 'undefined') { const b = Buffer.from(s, 'base64'); return new Uint8Array(b.buffer, b.byteOffset, b.byteLength).slice(); } const bin = atob(s), u = new Uint8Array(bin.length); for (let i = 0; i < bin.length; i++) u[i] = bin.charCodeAt(i); return u; };
export function encodeRecord(v) {
  if (ArrayBuffer.isView(v)) return { $ta: v.constructor.name, b64: b64(new Uint8Array(v.buffer, v.byteOffset, v.byteLength)) };
  if (Array.isArray(v)) return v.map(encodeRecord);
  if (v && typeof v === 'object') return Object.fromEntries(Object.entries(v).map(([k, x]) => [k, encodeRecord(x)]));
  if (typeof v === 'number' && !Number.isFinite(v)) return { $num: String(v) };
  return v;
}
export function decodeRecord(v) {
  if (ArrayBuffer.isView(v)) return v; // already decoded (a record from this browser's IndexedDB)
  if (Array.isArray(v)) return v.map(decodeRecord);
  if (v && typeof v === 'object') {
    if (typeof v.$ta === 'string' && TA[v.$ta]) { const u = unb64(v.b64); return new TA[v.$ta](u.buffer, u.byteOffset, u.byteLength / TA[v.$ta].BYTES_PER_ELEMENT); }
    if (typeof v.$num === 'string') return Number(v.$num);
    return Object.fromEntries(Object.entries(v).map(([k, x]) => [k, decodeRecord(x)]));
  }
  return v;
}
// what a list shows about a plan: { lengthM, gainM, lossM, points, segs, ended }
export function planMeta(p, joined) {
  return { lengthM: joined?.lengthM ?? null, gainM: joined?.gainM ?? null, lossM: joined?.lossM ?? null, points: p.points.length, segs: p.segs.length, ended: !!p.ended };
}
