// Roads the rider avoided on a route: a long press on the route opens the avoid modal, and "Avoid this road" keeps
// that road (the route's run between two junctions, as coordinates) in the route's own list (plan.avoids, saved with
// the route). A road graph is rebuilt from tiles or packs for every leg, so an avoid is matched to the graph each time:
// a road piece (atom) is closed when its midpoint lies within MATCH_M of the avoided line and runs within MATCH_DEG of
// its direction. Closed pieces cost Infinity (weights.mjs atomMultiplier), and the route search never rides them.
const MATCH_M = 12, MATCH_DEG = 30, KY = 110574;
const kxAt = (lat) => Math.cos((lat * Math.PI) / 180) * 111320;

export const newAvoid = (coords) => ({
  id: `a${Date.now().toString(36)}${Math.random().toString(36).slice(2, 6)}`,
  coords: coords.map(([x, y]) => [+x.toFixed(6), +y.toFixed(6)]),
});

export function distToLine([px, py], line) {
  const kx = kxAt(py); let best = Infinity;
  for (let i = 1; i < line.length; i++) {
    const ax = (line[i - 1][0] - px) * kx, ay = (line[i - 1][1] - py) * KY, bx = (line[i][0] - px) * kx, by = (line[i][1] - py) * KY;
    const dx = bx - ax, dy = by - ay, l2 = dx * dx + dy * dy || 1, u = Math.max(0, Math.min(1, -(ax * dx + ay * dy) / l2));
    best = Math.min(best, Math.hypot(ax + u * dx, ay + u * dy));
  }
  return line.length === 1 ? Math.hypot((line[0][0] - px) * kx, (line[0][1] - py) * KY) : best;
}
// heading (deg, 0..180: direction-free) of a line near a point
function headingNear([px, py], line) {
  const kx = kxAt(py); let best = Infinity, h = 0;
  for (let i = 1; i < line.length; i++) {
    const mx = ((line[i - 1][0] + line[i][0]) / 2 - px) * kx, my = ((line[i - 1][1] + line[i][1]) / 2 - py) * KY, d = Math.hypot(mx, my);
    if (d < best) { best = d; h = (Math.atan2((line[i][0] - line[i - 1][0]) * kx, (line[i][1] - line[i - 1][1]) * KY) * 180) / Math.PI; }
  }
  return ((h % 180) + 180) % 180;
}
// does a route line ride an avoided road? (one of the avoid's pieces lies on it, in its direction)
export function lineUses(coords, avoid) {
  const a = avoid.coords, mids = [];
  for (let i = 1; i < a.length; i++) mids.push([(a[i - 1][0] + a[i][0]) / 2, (a[i - 1][1] + a[i][1]) / 2]);
  if (!mids.length) mids.push(a[0]);
  return mids.some((p) => distToLine(p, coords) <= MATCH_M && (a.length < 2 || (() => { const dh = Math.abs(headingNear(p, a) - headingNear(p, coords)); return Math.min(dh, 180 - dh) <= MATCH_DEG; })()));
}

// per-atom factor for a graph (Float32Array: Infinity = closed, 0 = open), or null when no avoid is near it
export function avoidFactors(graph, chainCoords, avoids) {
  if (!avoids?.length || !graph?.nChains) return null;
  const pad = 0.0005, boxes = avoids.map((n) => { const xs = n.coords.map((c) => c[0]), ys = n.coords.map((c) => c[1]); return [Math.min(...xs) - pad, Math.min(...ys) - pad, Math.max(...xs) + pad, Math.max(...ys) + pad]; });
  const out = new Float32Array(graph.nAtoms); let any = false;
  for (let c = 0; c < graph.nChains; c++) {
    // cheap reject: every point of the chain outside every avoid's box
    let near = false;
    for (let k = graph.coordStart[c]; k < graph.coordStart[c + 1] && !near; k++) {
      const x = graph.coordLon[k], y = graph.coordLat[k];
      near = boxes.some(([x0, y0, x1, y1]) => x >= x0 && x <= x1 && y >= y0 && y <= y1);
    }
    if (!near) continue;
    const cs = chainCoords(graph, c), cum = [0];
    for (let q = 1; q < cs.length; q++) cum.push(cum[q - 1] + Math.hypot((cs[q][0] - cs[q - 1][0]) * kxAt(cs[q][1]), (cs[q][1] - cs[q - 1][1]) * KY));
    let La = 0; for (let i = graph.atomStart[c]; i < graph.atomStart[c + 1]; i++) La += graph.atomLen[i];
    let d = 0;
    for (let i = graph.atomStart[c]; i < graph.atomStart[c + 1]; i++) {
      const m = ((d + graph.atomLen[i] / 2) * cum.at(-1)) / (La || 1); let q = 1; while (q < cum.length - 1 && cum[q] < m) q++;
      const f = cum[q] > cum[q - 1] ? (m - cum[q - 1]) / (cum[q] - cum[q - 1]) : 0;
      const p = cs.length > 1 ? [cs[q - 1][0] + f * (cs[q][0] - cs[q - 1][0]), cs[q - 1][1] + f * (cs[q][1] - cs[q - 1][1])] : cs[0];
      const h = headingNear(p, cs);
      for (const n of avoids) {
        if (distToLine(p, n.coords) > MATCH_M) continue;
        if (n.coords.length > 1) { const dh = Math.abs(h - headingNear(p, n.coords)); if (Math.min(dh, 180 - dh) > MATCH_DEG) continue; }
        out[i] = Infinity; any = true;
      }
      d += graph.atomLen[i];
    }
  }
  return any ? out : null;
}
