// Route geometry for corridor analysis: a polyline (array of [lon, lat]) or a multi-part polyline
// (array of such arrays), buffered by bufM metres with round joins and caps. Shared by model.mjs (node
// selection), live/build-core.mjs (which tiles to fetch) and app.mjs (outline + mask drawing).
// Distances use a local equirectangular projection around the route's mean point (fine for < ~100 km).
// (The lowest-resistance route finder lives in best-route.mjs.)

// [[lon,lat],...] | [[[lon,lat],...], ...] -> array of non-empty parts
export function normalizeParts(input) {
  if (!Array.isArray(input) || !input.length) return [];
  const multi = Array.isArray(input[0]) && Array.isArray(input[0][0]);
  return (multi ? input : [input]).filter((p) => Array.isArray(p) && p.length).map((p) => p.map((q) => [+q[0], +q[1]]));
}

// The points a route must pass, in order: first, the must-pass waypoints, last (local metres, from selectCorridor).
// via: true = every waypoint; an array = indices into sel.waypoints of the must-pass ("pinned") points; else none.
export function stopPoints(sel, via) {
  const W = sel.waypoints ?? [];
  if (W.length > 2 && via === true) return W;
  if (W.length > 2 && Array.isArray(via)) {
    const mid = [...new Set(via)].filter((i) => i > 0 && i < W.length - 1).sort((a, b) => a - b);
    if (mid.length) return [sel.A, ...mid.map((i) => W[i]), sel.B];
  }
  return [sel.A, sel.B];
}

export function projectorAt(lon0, lat0) {
  const kx = Math.cos((lat0 * Math.PI) / 180) * 111320, ky = 110574;
  const proj = ([lon, lat]) => [(lon - lon0) * kx, (lat - lat0) * ky];
  proj.inv = ([x, y]) => [lon0 + x / kx, lat0 + y / ky];
  proj.kx = kx; proj.ky = ky; proj.lon0 = lon0; proj.lat0 = lat0;
  return proj;
}

// Projector centred on the mean of the route's points (two points: their midpoint, as before)
export function routeProjector(parts) {
  const pts = parts.flat();
  const lon0 = pts.reduce((s, p) => s + p[0], 0) / pts.length, lat0 = pts.reduce((s, p) => s + p[1], 0) / pts.length;
  return projectorAt(lon0, lat0);
}

// Distance (local metres) from (x, y) to the nearest segment of any part; single-point parts count as points.
export function distanceFn(parts, proj) {
  const segs = [];
  for (const part of parts) {
    const q = part.map(proj);
    if (q.length === 1) segs.push([q[0][0], q[0][1], q[0][0], q[0][1]]);
    for (let i = 1; i < q.length; i++) segs.push([q[i - 1][0], q[i - 1][1], q[i][0], q[i][1]]);
  }
  return (x, y) => {
    let best = Infinity;
    for (const [ax, ay, bx, by] of segs) {
      const dx = bx - ax, dy = by - ay, L2 = dx * dx + dy * dy;
      const u = L2 > 0 ? Math.max(0, Math.min(1, ((x - ax) * dx + (y - ay) * dy) / L2)) : 0;
      const d = Math.hypot(x - ax - u * dx, y - ay - u * dy);
      if (d < best) best = d;
    }
    return best;
  };
}

export function corridor(input, bufM) {
  const parts = normalizeParts(input);
  const proj = routeProjector(parts);
  const dist = distanceFn(parts, proj);
  const pts = parts.flat();
  let xmin = Infinity, ymin = Infinity, xmax = -Infinity, ymax = -Infinity;
  for (const p of pts) { const [x, y] = proj(p); xmin = Math.min(xmin, x); xmax = Math.max(xmax, x); ymin = Math.min(ymin, y); ymax = Math.max(ymax, y); }
  const [w, s] = proj.inv([xmin - bufM, ymin - bufM]), [e, n] = proj.inv([xmax + bufM, ymax + bufM]);
  return { parts, proj, dist, bufM, first: pts[0], last: pts[pts.length - 1], points: pts,
    bboxLocal: [xmin - bufM, ymin - bufM, xmax + bufM, ymax + bufM], bbox: [w, s, e, n] };
}

// Total length of the route in metres (sum over parts)
export function routeLength(input) {
  const parts = normalizeParts(input), proj = routeProjector(parts);
  let L = 0;
  for (const part of parts) for (let i = 1; i < part.length; i++) { const [ax, ay] = proj(part[i - 1]), [bx, by] = proj(part[i]); L += Math.hypot(bx - ax, by - ay); }
  return L;
}

// Outline of the buffered route (union of capsules) by marching squares on the distance field.
// Returns rings of [lon, lat] (closed), each tagged { outer: bool } -- outer rings bound the corridor,
// inner rings bound enclosed areas that are outside it (e.g. inside a loop).
export function corridorOutline(input, bufM, { cells = 160 } = {}) {
  const C = corridor(input, bufM);
  const [x0, y0, x1, y1] = C.bboxLocal;
  const h = Math.max(bufM / 24, Math.max(x1 - x0, y1 - y0) / cells);
  const nx = Math.ceil((x1 - x0) / h) + 3, ny = Math.ceil((y1 - y0) / h) + 3; // +padding so every contour closes
  const ox = x0 - h, oy = y0 - h;
  const f = new Float64Array(nx * ny);
  for (let j = 0; j < ny; j++) for (let i = 0; i < nx; i++) {
    const border = i === 0 || j === 0 || i === nx - 1 || j === ny - 1;
    f[j * nx + i] = border ? bufM : C.dist(ox + i * h, oy + j * h) - bufM; // < 0 inside
  }
  const v = (i, j) => f[j * nx + i];
  // crossing point on an edge, keyed so neighbouring cells share it
  const pts = new Map();
  const edgePt = (key, ia, ja, ib, jb) => {
    if (!pts.has(key)) {
      const a = v(ia, ja), b = v(ib, jb), t = a / (a - b);
      pts.set(key, [ox + (ia + t * (ib - ia)) * h, oy + (ja + t * (jb - ja)) * h]);
    }
    return key;
  };
  const adj = new Map();
  const link = (p, q) => { (adj.get(p) ?? adj.set(p, []).get(p)).push(q); (adj.get(q) ?? adj.set(q, []).get(q)).push(p); };
  for (let j = 0; j < ny - 1; j++) for (let i = 0; i < nx - 1; i++) {
    const a = v(i, j) < 0, b = v(i + 1, j) < 0, c = v(i + 1, j + 1) < 0, d = v(i, j + 1) < 0;
    const code = (a ? 1 : 0) | (b ? 2 : 0) | (c ? 4 : 0) | (d ? 8 : 0);
    if (code === 0 || code === 15) continue;
    const S = () => edgePt(`h${i},${j}`, i, j, i + 1, j), E = () => edgePt(`v${i + 1},${j}`, i + 1, j, i + 1, j + 1);
    const N = () => edgePt(`h${i},${j + 1}`, i, j + 1, i + 1, j + 1), W = () => edgePt(`v${i},${j}`, i, j, i, j + 1);
    const centre = (v(i, j) + v(i + 1, j) + v(i + 1, j + 1) + v(i, j + 1)) / 4 < 0;
    switch (code) {
      case 1: case 14: link(S(), W()); break;
      case 2: case 13: link(S(), E()); break;
      case 3: case 12: link(W(), E()); break;
      case 4: case 11: link(E(), N()); break;
      case 6: case 9: link(S(), N()); break;
      case 7: case 8: link(W(), N()); break;
      case 5: if (centre) { link(S(), E()); link(W(), N()); } else { link(S(), W()); link(E(), N()); } break;
      case 10: if (centre) { link(S(), W()); link(E(), N()); } else { link(S(), E()); link(W(), N()); } break;
    }
  }
  // walk closed rings
  const seen = new Set(), rings = [];
  for (const start of adj.keys()) {
    if (seen.has(start)) continue;
    const ring = [start]; seen.add(start);
    let prev = null, cur = start;
    for (;;) {
      const nb = adj.get(cur).find((q) => q !== prev && !seen.has(q));
      if (nb == null) break;
      ring.push(nb); seen.add(nb); prev = cur; cur = nb;
    }
    if (ring.length >= 3) rings.push(ring.map((k) => pts.get(k)));
  }
  // nesting depth by point-in-polygon: even depth = outer boundary, odd = hole in the corridor
  const inside = (p, r) => { let c = false; for (let a = 0, b = r.length - 1; a < r.length; b = a++) { const [xa, ya] = r[a], [xb, yb] = r[b]; if ((ya > p[1]) !== (yb > p[1]) && p[0] < ((xb - xa) * (p[1] - ya)) / (yb - ya) + xa) c = !c; } return c; };
  return rings.map((r, k) => {
    const depth = rings.reduce((s, o, m) => s + (m !== k && inside(r[0], o) ? 1 : 0), 0);
    const ll = r.map(C.proj.inv); ll.push(ll[0]);
    return { outer: depth % 2 === 0, coords: ll };
  });
}

// GeoJSON for the corridor: a dim mask outside it + dashed outline (same feature kinds as the area extent)
export function corridorExtentFC(input, bufM) {
  const rings = corridorOutline(input, bufM);
  const world = [[-180, -85], [180, -85], [180, 85], [-180, 85], [-180, -85]];
  const holes = rings.filter((r) => r.outer).map((r) => [...r.coords].reverse());
  return { type: 'FeatureCollection', features: [
    { type: 'Feature', properties: { kind: 'mask' }, geometry: { type: 'Polygon', coordinates: [world, ...holes] } },
    ...rings.filter((r) => !r.outer).map((r) => ({ type: 'Feature', properties: { kind: 'mask' }, geometry: { type: 'Polygon', coordinates: [r.coords] } })),
    ...rings.map((r) => ({ type: 'Feature', properties: { kind: 'outline' }, geometry: { type: 'LineString', coordinates: r.coords } })),
  ] };
}

// Slippy-map tiles at zoom z that intersect the buffered route
export function routeTiles(input, bufM, z) {
  const C = typeof input === 'object' && input.dist ? input : corridor(input, bufM);
  const n = 2 ** z;
  const tx = (lon) => Math.floor(((lon + 180) / 360) * n);
  const ty = (lat) => { const r = (lat * Math.PI) / 180; return Math.floor(((1 - Math.log(Math.tan(r) + 1 / Math.cos(r)) / Math.PI) / 2) * n); };
  const tLon = (x) => (x / n) * 360 - 180, tLat = (y) => (180 / Math.PI) * Math.atan(Math.sinh(Math.PI - (2 * Math.PI * y) / n));
  const [w, s, e, nn] = C.bbox, out = [];
  const segPts = [];
  for (const part of C.parts) {
    const q = part.map(C.proj);
    for (let i = 0; i < q.length; i++) {
      segPts.push(q[i]);
      if (i) for (let k = 1; k < 20; k++) segPts.push([q[i - 1][0] + ((q[i][0] - q[i - 1][0]) * k) / 20, q[i - 1][1] + ((q[i][1] - q[i - 1][1]) * k) / 20]);
    }
  }
  for (let x = tx(w); x <= tx(e); x++) for (let y = ty(nn); y <= ty(s); y++) {
    const [ax, ay1] = C.proj([tLon(x), tLat(y)]), [bx, ay0] = C.proj([tLon(x + 1), tLat(y + 1)]);
    let hit = false;
    for (let i = 0; i <= 8 && !hit; i++) for (let j = 0; j <= 8 && !hit; j++) if (C.dist(ax + ((bx - ax) * i) / 8, ay0 + ((ay1 - ay0) * j) / 8) <= C.bufM) hit = true;
    for (let k = 0; k < segPts.length && !hit; k++) { const [px, py] = segPts[k]; if (px >= ax && px <= bx && py >= ay0 && py <= ay1) hit = true; }
    if (hit) out.push({ z, x, y });
  }
  return out;
}
