// Long routes as legs. A route is a list of points [lon, lat, pin, label]; the stops (pin === 1) cut it into legs,
// each leg is built and routed on its own (app.mjs), and the legs' routes are joined into one here. Shaping points
// (pin 0) stay inside the leg they are in. Everything in this file is plain data in, plain data out (it runs in Node:
// test/tour.mjs).
import { coordsWithZ } from './best-route.mjs';

const KY = 110574, kxAt = (lat) => Math.cos((lat * Math.PI) / 180) * 111320;
export const metres = (a, b) => Math.hypot((a[0] - b[0]) * kxAt((a[1] + b[1]) / 2), (a[1] - b[1]) * KY);
export const samePlace = (a, b) => !!a && !!b && metres(a, b) < 1;
// a loop ends where it starts
export const isLoop = (pts) => pts.length >= 2 && samePlace(pts[0], pts[pts.length - 1]);

// The legs of a route: [{ from, to, pts }], from / to = indices of the leg's first and last point in `pts`, pts = the
// leg's own points as [lon, lat] (its two ends and the shaping points between them). No stops: one leg, the whole route.
export function splitLegs(pts) {
  const legs = [];
  for (let i = 1, a = 0; i < pts.length; i++) {
    if (i < pts.length - 1 && pts[i][2] !== 1) continue;
    legs.push({ from: a, to: i, pts: pts.slice(a, i + 1).map((p) => [p[0], p[1]]) });
    a = i;
  }
  return legs;
}
// a leg that goes nowhere: its ends are the same place (a loop without a stop, or two stops on one spot)
export const legIsEmpty = (leg) => samePlace(leg.pts[0], leg.pts[leg.pts.length - 1]);
export const legCrowM = (leg) => leg.pts.reduce((s, p, i) => (i ? s + metres(leg.pts[i - 1], p) : 0), 0);

// metres from point p to the straight piece a-b
function distToPiece(a, b, p) {
  const kx = kxAt(p[1]), ax = (a[0] - p[0]) * kx, ay = (a[1] - p[1]) * KY, dx = (b[0] - a[0]) * kx, dy = (b[1] - a[1]) * KY;
  const u = Math.max(0, Math.min(1, -(ax * dx + ay * dy) / (dx * dx + dy * dy || 1)));
  return Math.hypot(ax + u * dx, ay + u * dy);
}
// metres from point p to the line through `pts` (a leg's points: inside the search width means inside its corridor)
export const distToLine = (pts, p) => pts.reduce((best, q, i) => (i ? Math.min(best, distToPiece(pts[i - 1], q, p)) : best), Infinity);
// Where a new stop goes in leg [from, to] of `pts`: the index to insert it at, after the start of the nearest
// straight piece of that leg (so a leg with shaping points keeps them on the right side of the new stop).
export function insertIndex(pts, from, to, p) {
  let best = Infinity, at = from + 1;
  for (let i = from + 1; i <= to; i++) { const d = distToPiece(pts[i - 1], pts[i], p); if (d < best) { best = d; at = i; } }
  return at;
}

// Move stop number `n` (0-based among the stops of `mids`, the points between start and end) one place up (dir -1)
// or down (dir +1). The shaping points of the three legs that change are dropped: they shaped legs that no longer
// exist. Returns the new mids, or null when the stop cannot move that way.
export function moveStop(mids, n, dir) {
  const stops = [], shape = [[]]; // shape[j]: the shaping points before stop j (the last entry: after the last stop)
  for (const p of mids) { if (p[2] === 1) { stops.push(p); shape.push([]); } else shape[shape.length - 1].push(p); }
  const a = dir < 0 ? n - 1 : n, b = a + 1;
  if (a < 0 || b >= stops.length) return null;
  [stops[a], stops[b]] = [stops[b], stops[a]];
  shape[a] = []; shape[b] = []; shape[b + 1] = [];
  return stops.flatMap((s, j) => [...shape[j], s]).concat(shape[stops.length]);
}

// The route part of the link: 'lat,lon;lat,lon*;…' (* = a stop), or null when it would be longer than `max`
// characters (a long tour is left out of the link instead of making an enormous address).
export const HASH_ROUTE_MAX = 2000;
export function hashRoute(pts, max = HASH_ROUTE_MAX) {
  if (pts.length < 2) return null;
  const s = pts.map((q, i) => `${q[1].toFixed(5)},${q[0].toFixed(5)}${i > 0 && i < pts.length - 1 && q[2] === 1 ? '*' : ''}`).join(';');
  return s.length <= max ? s : null;
}

// Keep at most about n points of a [distance, z] profile for drawing: each bucket keeps its lowest and highest point,
// so passes and valleys survive. The ends are kept.
export function thinProfile(P, n) {
  if (!(P.length > n) || n < 4) return P;
  const out = [P[0]], buckets = Math.floor((n - 2) / 2), step = (P.length - 2) / buckets;
  for (let k = 0; k < buckets; k++) {
    const a = 1 + Math.floor(k * step), b = Math.min(P.length - 1, Math.max(a + 1, 1 + Math.floor((k + 1) * step)));
    let lo = a, hi = a;
    for (let i = a; i < b; i++) { if (P[i][1] < P[lo][1]) lo = i; if (P[i][1] > P[hi][1]) hi = i; }
    out.push(P[Math.min(lo, hi)]); if (lo !== hi) out.push(P[Math.max(lo, hi)]);
  }
  out.push(P[P.length - 1]);
  return out;
}

// Join the legs' routes (best-route.mjs results, in order) into one route of the same shape, so the summary, the
// elevation strip, the flyover and the exports take it like a single route. A leg not worked out yet is null: the
// result then has complete: false and holds what there is. Extra fields:
//   coords     [lon, lat, z] when the legs have elevation (z worked out leg by leg, so it does not drift)
//   lines      one coordinate list per finished leg (for drawing an unfinished route)
//   legs       per leg (null when missing): { fromM, lengthM, gainM, lossM, c0, c1 (its coords are c0 .. c1), gapM }
//   segments   every leg's steepness segments, `from_m` counted from the start of the whole route, `leg` = leg number
//   traffic, bike   sums of the per-leg figures the app attaches (route.traffic { mean, busyM, lenM }, route.bike)
export function joinLegs(routes) {
  const coords = [], lines = [], profile = [], features = [], legs = [], byClass = {};
  const sum = { lengthM: 0, resistance: 0, steepM: 0, tunnelM: 0, tunnelAvoidM: 0, unpavedM: 0, aboveM: 0, shortestM: 0, gainM: 0, lossM: 0, gainRawM: 0, lossRawM: 0, climbEstimateM: 0 };
  const turns = { count: 0, right: 0, left: 0, busy: 0, signals: 0, costM: 0 };
  const bike = { sep: 0, shared: 0, lane: 0 }, traffic = { lenM: 0, vl: 0, busyM: 0 };
  let hasZ = true, hasTurns = false, hasBike = false, RL = 0, minZ = Infinity, maxZ = -Infinity, complete = true, tunnelFreeRef = false, rough = false, detourBound = false;
  routes.forEach((r, k) => {
    if (!r || r.error || !(r.coords?.length >= 2)) { legs.push(null); complete = false; return; }
    const off = sum.lengthM, cz = coordsWithZ(r), c0 = coords.length ? coords.length - 1 : 0;
    const gapM = coords.length ? metres(coords[coords.length - 1], cz[0]) : 0;
    // the next leg starts at the junction the last one ended at: one point, not two (a gap stays as a straight join)
    for (let i = coords.length && gapM < 1 ? 1 : 0; i < cz.length; i++) coords.push(cz[i]);
    lines.push(cz);
    for (const key of Object.keys(sum)) sum[key] += r[key] ?? 0;
    RL += (r.meanMultiplier ?? 0) * r.lengthM;
    if (r.gainM == null || !r.profile?.length) hasZ = false;
    else { for (const [d, z] of r.profile) profile.push([off + d, z]); minZ = Math.min(minZ, r.minZ); maxZ = Math.max(maxZ, r.maxZ); }
    for (const f of r.segments?.features ?? []) features.push({ type: 'Feature', properties: { ...f.properties, from_m: off + f.properties.from_m, leg: k }, geometry: f.geometry });
    if (r.turns) { hasTurns = true; for (const key of Object.keys(turns)) turns[key] += r.turns[key] ?? 0; }
    if (r.bike) { hasBike = true; for (const key of Object.keys(bike)) bike[key] += r.bike[key] ?? 0; }
    if (r.traffic) { traffic.lenM += r.traffic.lenM; traffic.vl += r.traffic.mean * r.traffic.lenM; traffic.busyM += r.traffic.busyM; }
    for (const [rc, m] of Object.entries(r.byClass ?? {})) byClass[rc] = (byClass[rc] ?? 0) + m;
    tunnelFreeRef ||= !!r.tunnelFreeRef; rough ||= !!r.rough; detourBound ||= !!r.detourBound;
    legs.push({ fromM: off, lengthM: r.lengthM, gainM: r.gainM, lossM: r.lossM, c0: gapM < 1 ? c0 : c0 + 1, c1: coords.length - 1, gapM });
  });
  const z = hasZ && profile.length > 0;
  return { ...sum, complete, coords, lines, legs, byClass, tunnelFreeRef, rough, detourBound,
    gainM: z ? sum.gainM : null, lossM: z ? sum.lossM : null, gainRawM: z ? sum.gainRawM : null, lossRawM: z ? sum.lossRawM : null,
    profile: z ? profile : null, minZ: z ? minZ : null, maxZ: z ? maxZ : null,
    meanMultiplier: sum.lengthM ? RL / sum.lengthM : 0, detourPct: sum.shortestM ? 100 * (sum.lengthM / sum.shortestM - 1) : 0,
    turns: hasTurns ? turns : null, bike: hasBike ? bike : null,
    traffic: traffic.lenM ? { mean: traffic.vl / traffic.lenM, busyM: traffic.busyM, lenM: traffic.lenM } : null,
    segments: { type: 'FeatureCollection', features } };
}
// what the exports take: the joined coords already carry z, so the profile must not be laid over them again
export const forExport = (route) => (route.legs ? { ...route, profile: null } : route);

// ---- a route result packed into typed arrays (a saved route in IndexedDB), and back ----
// A route's line and steepness segments are tens of thousands of small arrays; packed they are a few flat arrays,
// which IndexedDB stores as they are (16 bytes a point instead of an object each). Numbers survive unchanged.
const SCALARS = ['lengthM', 'resistance', 'meanMultiplier', 'steepM', 'tunnelM', 'tunnelAvoidM', 'unpavedM', 'aboveM', 'shortestM', 'detourPct', 'gainM', 'lossM',
  'gainRawM', 'lossRawM', 'minZ', 'maxZ', 'climbEstimateM', 'tunnelFreeRef', 'detourBound', 'rough', 'turns', 'bike', 'traffic', 'byClass', 'throughTunnels', 'tunnelAlt', 'line', 'snap'];
const flat = (rows, w) => { const a = new Float64Array(rows.length * w); rows.forEach((r, i) => { for (let j = 0; j < w; j++) a[i * w + j] = r[j]; }); return a; };
const rows = (a, w) => { const out = []; for (let i = 0; i < a.length; i += w) out.push(Array.from(a.subarray(i, i + w))); return out; };
export function packRoute(r) {
  const fs = r.segments?.features ?? [], start = new Int32Array(fs.length + 1), xy = [];
  fs.forEach((f, i) => { for (const c of f.geometry.coordinates) xy.push(c); start[i + 1] = xy.length; });
  const prop = (k) => Float64Array.from(fs, (f) => f.properties[k]);
  return { v: 1, ...Object.fromEntries(SCALARS.filter((k) => r[k] !== undefined).map((k) => [k, r[k]])),
    coords: flat(r.coords, 2), profile: r.profile ? flat(r.profile, 2) : null, runs: r.runs ? flat(r.runs, 2) : null,
    seg: { start, xy: flat(xy, 2), bin: Uint8Array.from(fs, (f) => f.properties.bin), tunnel: Uint8Array.from(fs, (f) => f.properties.tunnel),
      grade: prop('grade_pct'), len: prop('len_m'), from: prop('from_m') } };
}
export function unpackRoute(p) {
  const { v, coords, profile, seg, runs, ...scalars } = p, xy = rows(seg.xy, 2), features = [];
  for (let i = 0; i + 1 < seg.start.length; i++) features.push({ type: 'Feature',
    properties: { bin: seg.bin[i], grade_pct: seg.grade[i], len_m: seg.len[i], from_m: seg.from[i], tunnel: seg.tunnel[i] },
    geometry: { type: 'LineString', coordinates: xy.slice(seg.start[i], seg.start[i + 1]) } });
  return { ...scalars, coords: rows(coords, 2), profile: profile ? rows(profile, 2) : null, runs: runs ? rows(runs, 2) : null, alternatives: [], segments: { type: 'FeatureCollection', features } };
}
