// Map tiles kept in Cache Storage, one cache per source, so repeat runs over the same area don't refetch and either
// source's tiles can be cleared on their own. Each stored tile carries the time it was fetched (header STAMP). A tile
// older than MAX_AGE_MS is fetched again when it is next needed and replaced, so roads and paths added to the map since
// do turn up; if that fetch fails (offline, the host is down) the old copy is used. Tiles stored before there were
// stamps get one on first use and age from then. Shared by the build worker and the app (size, "Clear downloaded map
// data"); runs in Node for test/tile-cache.mjs (Response is all it needs).
export const TILE_CACHES = { gsi: 'gsi-tiles-v1', osm: 'osm-tiles-v1', osmjp: 'osm-tiles-v1' }; // osmjp: VersaTiles roads and GSI heights, one cache
export const MAX_AGE_MS = 30 * 24 * 3600 * 1000, STAMP = 'x-fetched';
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

// cache: a Cache, or null (no Cache Storage: plain fetches). Returns { bytes: Uint8Array | null (no such tile: sea,
// outside the data), cached: true when no request was made }.
export async function cachedTile(cache, url, { net = (u) => fetch(u, { mode: 'cors' }), now = () => Date.now(), maxAgeMs = MAX_AGE_MS, wait = sleep } = {}) {
  const body = async (res) => (res.status === 200 ? new Uint8Array(await res.arrayBuffer()) : null);
  const store = (status, buf, type) => cache?.put(url, new Response(status === 200 ? buf : null,
    { status, headers: { [STAMP]: String(now()), ...(status === 200 ? { 'content-type': type ?? 'application/octet-stream' } : {}) } })).catch(() => {});
  let old = null; // a copy past its age, kept in case the fetch fails
  const hit = cache ? await cache.match(url) : null;
  if (hit) {
    const at = Number(hit.headers.get(STAMP)), bytes = await body(hit);
    if (!at) await store(hit.status, bytes, hit.headers.get('content-type'));
    if (!at || now() - at <= maxAgeMs) return { bytes, cached: true };
    old = { bytes, cached: true };
  }
  for (let attempt = 1; ; attempt++) {
    let res;
    try { res = await net(url); } catch (e) { if (attempt >= 3) { if (old) return old; throw e; } await wait(500 * attempt); continue; }
    if (res.status === 404) { await store(404); return { bytes: null, cached: false }; } // sea / no data: remember the miss too
    if (!res.ok) { if (attempt >= 3) { if (old) return old; throw new Error(`HTTP ${res.status} for ${url}`); } await wait(1000 * attempt); continue; }
    const buf = await res.arrayBuffer();
    await store(200, buf, res.headers.get('content-type'));
    return { bytes: new Uint8Array(buf), cached: false };
  }
}

// Bytes of downloaded map data in this browser, or null when it cannot tell. Chromium reports Cache Storage on its own;
// elsewhere it is everything the page has stored, which is the tiles but for a few kilobytes of settings.
export async function tileCacheBytes() {
  try { const e = await navigator.storage.estimate(); return e.usageDetails?.caches ?? e.usage ?? null; } catch { return null; }
}
export const clearTileCaches = () => Promise.all(Object.values(TILE_CACHES).map((name) => caches.delete(name)));
