// The route's start and end flags as map markers (inline SVG, no image files). Both are the same flag on its pole,
// after "Checkered flag" by Road Signs (The Noun Project 13118, public domain):
//   start: a solid green cloth
//   end:   a checkered cloth, its background white so the checks read on any basemap
// A white outline keeps either readable on any basemap. Each marker's anchor is the pole's foot (MapLibre Marker
// anchor + offset). On a loop both flags stand on one point, so the start flag is mirrored and waves the other way.

// the checks: 4 columns x 3 rows over the cloth, clipped to its waving outline
const checks = () => { let s = ''; for (let r = 0; r < 3; r++) for (let c = 0; c < 4; c++) if ((r + c) % 2 === 0) s += `<rect x="${6 + 7 * c}" y="${1 + 7 * r}" width="7" height="7"/>`; return s; };
const CLOTH = 'M6 5.5 C13 1.5 20 9.5 27 5.5 C30 3.8 32 3.8 34 4.8 L34 21 C32 20 30 20 27 21.6 C20 25.6 13 17.6 6 21.6 Z';
// one flag: the cloth's fill, what is drawn on it (clipped to the cloth), and its outline colour
const flagSvg = (id, fill, inner, edge) => `<svg viewBox="0 0 36 46" width="36" height="46" aria-hidden="true">
  <defs><clipPath id="${id}"><path d="${CLOTH}"/></clipPath></defs>
  <ellipse cx="5.5" cy="43.8" rx="4.5" ry="1.6" fill="#000" opacity=".35"/>
  <line x1="5" y1="2.5" x2="5" y2="43" stroke="#fff" stroke-width="5" stroke-linecap="round"/>
  <path d="${CLOTH}" fill="${fill}" stroke="#fff" stroke-width="3.2" stroke-linejoin="round"/>
  ${inner ? `<g clip-path="url(#${id})" fill="#111">${inner}</g>` : ''}
  <path d="${CLOTH}" fill="none" stroke="${edge}" stroke-width="1.4" stroke-linejoin="round"/>
  <line x1="5" y1="2.5" x2="5" y2="43" stroke="#111" stroke-width="2.6" stroke-linecap="round"/>
</svg>`;
const START_SVG = flagSvg('fl-s', '#1fb257', '', '#0b4d24');
const END_SVG = flagSvg('fl-c', '#fff', checks(), '#111');

function el(cls, svg, title) {
  const d = document.createElement('div');
  d.className = `flag ${cls}`; d.innerHTML = svg; d.title = title; d.setAttribute('role', 'button'); d.setAttribute('aria-label', title);
  return d;
}
// { element, anchor, offset } for new maplibregl.Marker(...)
export const startFlag = (title = 'Start', { mirror = false } = {}) => mirror
  ? { element: el('flag-start mirror', START_SVG, title), anchor: 'bottom-right', offset: [5, 3] }
  : { element: el('flag-start', START_SVG, title), anchor: 'bottom-left', offset: [-5, 3] };
export const endFlag = (title = 'End') => ({ element: el('flag-end', END_SVG, title), anchor: 'bottom-left', offset: [-5, 3] });
