// Snap mode: the route follows the roads exactly where the rider taps. Each tap is snapped onto the nearest road (the
// nearest point of the nearest chain polyline, not the nearest junction), and the road graph gets a junction there:
// the chain is cut in two at that point, its road piece (atom) too, with lengths and heights shared out. The route
// between two such junctions is then the shortest way along the roads (weights.mjs P.flat), found by the ordinary
// route search on the cut graph, so the result has the same shape as every other route (best-route.mjs).
// Pure: graph in, graph out (CONTRACT.md §2 typed graph); it runs in Node (test/snap.mjs).
import { chainCoords } from './graph-io.mjs';

const KY = 110574, kxAt = (lat) => Math.cos((lat * Math.PI) / 180) * 111320;

// The nearest point of any chain to `ll` ([lon, lat]) within maxM: { c, d (metres along the chain's polyline from its
// start), ll (the point on the road), distM }, or null. A sidewalk (atomFlags 64) counts SIDEWALK_M further away than
// it is, so a tap by the kerb lands on the road and not on the pavement beside it.
const SIDEWALK_M = 20;
export function snapPoint(graph, ll, { maxM = 1000 } = {}) {
  const [px, py] = ll, kx = kxAt(py), dLon = maxM / kx, dLat = maxM / KY;
  let best = null, bestScore = Infinity;
  for (let c = 0; c < graph.nChains; c++) {
    let along = 0; const pen = graph.atomFlags?.[graph.atomStart[c]] & 64 ? SIDEWALK_M : 0;
    for (let k = graph.coordStart[c] + 1; k < graph.coordStart[c + 1]; k++) {
      const x0 = graph.coordLon[k - 1], y0 = graph.coordLat[k - 1], x1 = graph.coordLon[k], y1 = graph.coordLat[k];
      const ax = (x0 - px) * kx, ay = (y0 - py) * KY, dx = (x1 - x0) * kx, dy = (y1 - y0) * KY, L = Math.hypot(dx, dy);
      if (!(Math.min(x0, x1) > px + dLon || Math.max(x0, x1) < px - dLon || Math.min(y0, y1) > py + dLat || Math.max(y0, y1) < py - dLat)) {
        const u = L ? Math.max(0, Math.min(1, -(ax * dx + ay * dy) / (L * L))) : 0, d = Math.hypot(ax + u * dx, ay + u * dy);
        if (d <= maxM && d + pen < bestScore) { bestScore = d + pen; best = { c, d: along + u * L, ll: [x0 + u * (x1 - x0), y0 + u * (y1 - y0)], distM: d }; }
      }
      along += L;
    }
  }
  return best;
}

// metres along chain c's polyline (in the projection snapPoint uses at latitude lat0)
function chainGeomLen(graph, c, kx) {
  let L = 0;
  for (let k = graph.coordStart[c] + 1; k < graph.coordStart[c + 1]; k++) L += Math.hypot((graph.coordLon[k] - graph.coordLon[k - 1]) * kx, (graph.coordLat[k] - graph.coordLat[k - 1]) * KY);
  return L;
}

// Cut chain c at d metres along its polyline. Returns { graph, node }: a new graph with a junction `node` there (the
// chain keeps its first part and a new last chain holds the rest), or the same graph and an end node when d is
// within END_M of an end. The input graph is not changed.
const END_M = 0.5;
export function cutChain(graph, c, d, kx = kxAt(graph.coordLat[graph.coordStart[c]])) {
  const Lg = chainGeomLen(graph, c, kx);
  if (d <= END_M) return { graph, node: graph.chainA[c] };
  if (d >= Lg - END_M) return { graph, node: graph.chainB[c] };
  const s = graph.coordStart[c], e = graph.coordStart[c + 1];
  // the polyline piece holding d, and the cut point
  let q = s + 1, along = 0;
  for (; q < e; q++) {
    const L = Math.hypot((graph.coordLon[q] - graph.coordLon[q - 1]) * kx, (graph.coordLat[q] - graph.coordLat[q - 1]) * KY);
    if (along + L >= d || q === e - 1) { const f = L ? Math.min(1, Math.max(0, (d - along) / L)) : 0; var P = [graph.coordLon[q - 1] + f * (graph.coordLon[q] - graph.coordLon[q - 1]), graph.coordLat[q - 1] + f * (graph.coordLat[q] - graph.coordLat[q - 1])]; break; }
    along += L;
  }
  // the atom holding d (atoms are spread along the polyline in proportion to their lengths, as the builder draws them)
  const a0 = graph.atomStart[c], a1 = graph.atomStart[c + 1];
  let La = 0; for (let i = a0; i < a1; i++) La += graph.atomLen[i];
  const da = (d / Lg) * La;
  let ai = a0, acc = 0;
  while (ai < a1 - 1 && acc + graph.atomLen[ai] < da) { acc += graph.atomLen[ai]; ai++; }
  const fa = graph.atomLen[ai] ? Math.min(1, Math.max(0, (da - acc) / graph.atomLen[ai])) : 0;
  const splitAtom = fa > 1e-6 && fa < 1 - 1e-6; // else the cut falls on an atom boundary
  const firstEnd = splitAtom ? ai + 1 : fa >= 1 - 1e-6 ? ai + 1 : ai; // atoms [a0, firstEnd) go to the first part (the split atom's front included)
  const nN = graph.nNodes + 1, nC = graph.nChains + 1, nA = graph.nAtoms + (splitAtom ? 1 : 0), nX = graph.coordLon.length + 2;
  const node = graph.nNodes, cNew = graph.nChains;
  const g = { ...graph, meta: graph.meta, nNodes: nN, nChains: nC, nAtoms: nA };
  const grow = (arr, n) => { const out = new arr.constructor(n); return out; };
  for (const [k, v] of Object.entries(graph)) {
    if (!ArrayBuffer.isView(v) || k === 'atomStart' || k === 'coordStart') continue;
    if (k.startsWith('node')) { const o = grow(v, nN); o.set(v); g[k] = o; }
    else if (k.startsWith('chain')) { const o = grow(v, nC); o.set(v); g[k] = o; }
  }
  g.nodeLon[node] = P[0]; g.nodeLat[node] = P[1];
  g.chainB[cNew] = graph.chainB[c]; g.chainA[cNew] = node; g.chainB[c] = node;
  for (const k of Object.keys(g)) if (k.startsWith('chain') && k !== 'chainA' && k !== 'chainB' && ArrayBuffer.isView(g[k])) g[k][cNew] = graph[k][c];
  // atoms: every chain's atoms in order, chain c cut short, the new chain's at the end
  const atomKeys = Object.keys(graph).filter((k) => k.startsWith('atom') && k !== 'atomStart' && ArrayBuffer.isView(graph[k]));
  for (const k of atomKeys) g[k] = grow(graph[k], nA);
  const atomStart = new Int32Array(nC + 1);
  let w = 0;
  const copyAtom = (i) => { for (const k of atomKeys) g[k][w] = graph[k][i]; return w++; };
  const hasZ = !!(graph.atomZ0 && graph.atomZ1);
  for (let cc = 0; cc < graph.nChains; cc++) {
    atomStart[cc] = w;
    if (cc !== c) { for (let i = graph.atomStart[cc]; i < graph.atomStart[cc + 1]; i++) copyAtom(i); continue; }
    for (let i = a0; i < firstEnd; i++) {
      const j = copyAtom(i);
      if (splitAtom && i === ai) {
        g.atomLen[j] = graph.atomLen[i] * fa;
        if (hasZ) g.atomZ1[j] = graph.atomZ0[i] + fa * (graph.atomZ1[i] - graph.atomZ0[i]);
      }
    }
  }
  atomStart[graph.nChains] = w;
  for (let i = splitAtom ? ai : firstEnd; i < a1; i++) {
    const j = copyAtom(i);
    if (splitAtom && i === ai) {
      g.atomLen[j] = graph.atomLen[i] * (1 - fa);
      if (hasZ) g.atomZ0[j] = graph.atomZ0[i] + fa * (graph.atomZ1[i] - graph.atomZ0[i]);
    }
  }
  atomStart[nC] = w;
  // a chain needs at least one atom: a cut right at the start or end of the atoms (rounding) keeps an empty part out
  if (atomStart[c + 1] - atomStart[c] === 0 || atomStart[nC] - atomStart[nC - 1] === 0) return { graph, node: atomStart[c + 1] - atomStart[c] === 0 ? graph.chainA[c] : graph.chainB[c] };
  g.atomStart = atomStart;
  // coordinates: chain c up to the cut point, the new chain from it
  const coordKeys = Object.keys(graph).filter((k) => k.startsWith('coord') && k !== 'coordStart' && ArrayBuffer.isView(graph[k]));
  for (const k of coordKeys) g[k] = grow(graph[k], nX);
  const coordStart = new Int32Array(nC + 1);
  let x = 0;
  const copyCoord = (i) => { for (const k of coordKeys) g[k][x] = graph[k][i]; x++; };
  const putP = () => { g.coordLon[x] = P[0]; g.coordLat[x] = P[1]; for (const k of coordKeys) if (k !== 'coordLon' && k !== 'coordLat') g[k][x] = 0; x++; };
  for (let cc = 0; cc < graph.nChains; cc++) {
    coordStart[cc] = x;
    if (cc !== c) { for (let i = graph.coordStart[cc]; i < graph.coordStart[cc + 1]; i++) copyCoord(i); continue; }
    for (let i = s; i < q; i++) copyCoord(i);
    putP();
  }
  coordStart[graph.nChains] = x;
  putP();
  for (let i = q; i < e; i++) copyCoord(i);
  coordStart[nC] = x;
  g.coordStart = coordStart;
  return { graph: g, node };
}

// Both ends of a Snap leg: each point snapped onto the nearest road and the graph cut there. Returns { graph, a, b }
// (a / b: the points on the road), or null when a point has no road within maxM.
export function snapEnds(graph, a, b, opts) {
  const sa = snapPoint(graph, a, opts); if (!sa) return null;
  const ca = cutChain(graph, sa.c, sa.d, kxAt(a[1]));
  const sb = snapPoint(ca.graph, b, opts); if (!sb) return null;
  const cb = cutChain(ca.graph, sb.c, sb.d, kxAt(b[1]));
  const at = (g, n) => [g.nodeLon[n], g.nodeLat[n]];
  return { graph: cb.graph, a: at(cb.graph, ca.node), b: at(cb.graph, cb.node), na: ca.node, nb: cb.node, distA: sa.distM, distB: sb.distM };
}

export { chainCoords };
